schema={'schema_version':'1.0','sheets':[]}
for name,fields in specs.items():
    schema['sheets'].append({'name':name,'columns':[dict(key=f[0],label=f[1],type=f[2],required_when=f[3],description=f[4],unit=('bp' if f[2]=='bp' else '0—1比例' if f[2]=='ratio' else '')) for f in fields]})
funds=list(csv.DictReader(SOURCE.open(encoding='utf-8-sig')))
assert len(funds)==210 and len({f['ETF代码'] for f in funds})==210
ledger={s['name']:[] for s in schema['sheets']}
phases=[('G01','工作区与输入锁定','LOCATION、源manifest、候选唯一性检查',''),('G02','隔离复现520600','全部模型计数一致及数值误差≤1e-8','G01'),('G03','参数化与回归验证','520600新旧一致及第二标的冒烟通过','G02'),('G04','210条候选分类和覆盖','逐条官方证据或真实缺口、队列锁定','G01'),('G05','逐基金批处理','所有基金任务均有终态、五步骤齐全或明确缺口','G03;G04'),('G06','汇总和最终验收','分母210对账、全部检查、Excel及FINAL_HANDOFF','G05')]
for i,(tid,obj,acc,dep) in enumerate(phases):
    ledger['任务台账'].append(dict(task_id=tid,phase=tid,priority=i+1,depends_on=dep,status='TODO',objective=obj,acceptance=acc,next_step='依照任务书执行'))
for f in funds:
    code=f['ETF代码']
    ledger['基金目录'].append(dict(fund_id=code,fund_name=f['基金全称'],index_code=f['跟踪指数代码'],index_name=f['跟踪指数名称'],listing_date=f['上市日期'] or None,classification='UNVERIFIED',channel='UNKNOWN',task_status='TODO',reason='原始名称发现池，尚未由Luna核验'))
    ledger['任务台账'].append(dict(task_id='F-'+code,fund_id=code,phase='S1-S5',priority=10 if code=='520600.SH' else 20,depends_on='G03;G04',status='TODO',objective='分类、数据与事件、固定外测、敏感性、报告和台账',acceptance='五步证据齐全；或有证据的范围外/历史不足/真实阻塞终态',next_step='先核验分类及覆盖，再按锁定队列执行'))
now = datetime.now(timezone(timedelta(hours=8))).isoformat(timespec='seconds')
for row in ledger['任务台账']:
    row['updated_at'] = now
(ROOT/'schema.json').write_text(json.dumps(schema,ensure_ascii=False,indent=2))
(ROOT/'ledger.json').write_text(json.dumps({'schema_version':'1.0','records':ledger},ensure_ascii=False,indent=2))
print(json.dumps({'candidate_count':len(funds),'task_count':len(ledger['任务台账']),'field_count':sum(len(s['columns']) for s in schema['sheets'])}))
